import XCTest
@testable import Stello

/// Folder ingest (folder engine plan 4b, part 3): FolderIngest must take the same links,
/// ids and new items from the person's own files as the web's src/lib/folder-ingest.js.
/// Expected output: test/fixtures/folder-ingest.json (FolderIngestFixtures, generated by
/// scripts/make-folder-ingest-fixtures.mjs). Web twin: test/folder-ingest.test.js.
final class FolderIngestTests: XCTestCase {
    typealias W = FolderWriter
    typealias I = FolderIngest

    private var cases: [W.JSON] { W.parse(FolderIngestFixtures.json)?["cases"]?.array ?? [] }

    func testSampleFilesGiveTheWebsLinksIdsAndItems() throws {
        XCTAssertFalse(cases.isEmpty)
        for c in cases {
            let path = c["path"]!.string!
            let expect = c["expect"]!
            XCTAssertEqual(I.ingestType(path), expect["type"]?.string, path)
            let modified = Date(timeIntervalSince1970: (c["modified"]?.number ?? 0) / 1000)
            let links = I.readLinks(path: path, text: c["text"]?.string ?? "", modified: modified)
            let want = expect["links"]?.array ?? []
            XCTAssertEqual(links.count, want.count, "\(path): \(links.map(\.key))")
            for (i, (l, w)) in zip(links, want).enumerated() {
                let name = "\(path) link \(i)"
                XCTAssertEqual(l.url, w["url"]?.string, name)
                XCTAssertEqual(l.key, w["key"]?.string, name)
                XCTAssertEqual(l.title, w["title"]?.string, name)
                XCTAssertEqual(l.note, w["note"]?.string, name)
                XCTAssertEqual(l.summary, w["summary"]?.string, name)
                XCTAssertEqual(l.tags, (w["tags"]?.array ?? []).compactMap(\.string), name)
                XCTAssertEqual(l.added, w["added"]?.string, name)
                let item = expect["items"]!.array![i]
                let id = I.linkItemID(l.key)
                XCTAssertEqual(id.uuidString.lowercased(), item["id"]?.string, name)
                let f = item["change"]!["fields"]!
                let n = I.newItem(l, id: id, now: c["now"]!.string!)
                XCTAssertEqual(n.slug, f["slug"]?.string, name)
                XCTAssertEqual(n.title, f["title"]?.string, name)
                XCTAssertEqual(n.sourceURL, f["source_url"]?.string, name)
                XCTAssertEqual(n.domain, f["domain"]?.string, name)
                XCTAssertEqual(n.summary, f["summary"]?.string, name)
                XCTAssertEqual(n.body, f["body_markdown"]?.string, name)
                XCTAssertEqual(n.addedAt, f["added_at"]?.string, name)
                XCTAssertEqual(n.tags, (f["tags"]?.array ?? []).compactMap { $0["tag"]?.string }, name)
            }
        }
    }

    func testOneLinkOneIDWhateverItsTrackingBits() {
        let a = I.readLinks(path: "a.md", text: "https://www.Example.com/x/?utm_source=a#top", modified: nil)
        let b = I.readLinks(path: "b.csv", text: "url\nhttp://example.com/x\n", modified: nil)
        XCTAssertEqual(a.first?.key, b.first?.key)
        XCTAssertEqual(a.first.map { I.linkItemID($0.key) }, b.first.map { I.linkItemID($0.key) })
    }

    func testBigSheetReadsQuickly() {
        var rows = ["title,url,tags"]
        for i in 0..<7000 { rows.append("Item \(i),https://site\(i % 50).example/p/\(i),\"a, b\"") }
        let text = rows.joined(separator: "\n")
        let start = Date()
        let links = I.readLinks(path: "big.csv", text: text, modified: nil)
        XCTAssertEqual(links.count, 7000)
        XCTAssertLessThan(Date().timeIntervalSince(start), 10, "a 7,000-row sheet must stay well inside the 15-minute import budget")
    }

    func testScanFindsTheFoldersOwnFilesOnlyWhenAsked() throws {
        let root = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let fm = FileManager.default
        try fm.createDirectory(at: root.appendingPathComponent("items/2026/11"), withIntermediateDirectories: true)
        try "---\nid: \"a\"\n---\n".write(to: root.appendingPathComponent("items/2026/11/a.md"), atomically: true, encoding: .utf8)
        try "- https://example.com/x".write(to: root.appendingPathComponent("links.md"), atomically: true, encoding: .utf8)
        try "url\nhttps://example.com/y\n".write(to: root.appendingPathComponent("sheet.csv"), atomically: true, encoding: .utf8)
        try "no".write(to: root.appendingPathComponent("photo.jpg"), atomically: true, encoding: .utf8)

        let (off, none) = FolderScanner.scan(root: root, previous: [:], previousFound: [:], ingest: false)
        guard case .success(let files, _) = off else { return XCTFail("scan failed") }
        XCTAssertEqual(files.mapValues(\.id), ["items/2026/11/a.md": "a"])
        XCTAssertTrue(none.isEmpty)

        let (_, found) = FolderScanner.scan(root: root, previous: [:], previousFound: [:], ingest: true)
        XCTAssertEqual(Set(found.keys), ["links.md", "sheet.csv"])
        XCTAssertTrue(found.values.allSatisfy { $0.stale == true })

        // Read files that haven't changed keep their links and aren't read again.
        var read = found
        for k in read.keys { read[k]?.stale = nil; read[k]?.links = [.init(key: "k", id: "i")] }
        let (_, again) = FolderScanner.scan(root: root, previous: files, previousFound: read, ingest: true)
        XCTAssertEqual(again, read)
        let parsed = FolderSources.readFiles(root: root, paths: ["links.md", "sheet.csv"])
        XCTAssertEqual(parsed.flatMap { $0.links.map(\.key) }.sorted(), ["https://example.com/x", "https://example.com/y"])
    }
}
